package app.cs23c02.companion.core

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class ActivationCodeTest {
    // Generated by backend/app/activation/codes.py; the app must agree with the server on every one.
    private val serverCodes = listOf("Z83G-BHAB-JD4T-H5BB", "6EC6-T953-Z6T8-6TMC", "VCF0-YMC1-8T1V-11CK", "3ASV-D0QG-C93P-M7ZX")

    @Test fun acceptsCodesGeneratedByTheServer() =
        serverCodes.forEach { assertTrue(it, ActivationCode.checksumOk(ActivationCode.clean(it))) }

    @Test fun checkCharacterMatchesServer() = serverCodes.map(ActivationCode::clean).forEach {
        assertEquals(it.last(), ActivationCode.checkChar(it.dropLast(1)))
    }

    @Test fun anySingleCharacterTypoIsCaught() {
        val code = ActivationCode.clean(serverCodes[0])
        for (i in code.indices) for (c in ActivationCode.ALPHABET) {
            if (c == code[i]) continue
            val typo = code.substring(0, i) + c + code.substring(i + 1)
            assertFalse("typo at $i -> $c", ActivationCode.checksumOk(typo))
        }
    }

    @Test fun adjacentSwapIsCaught() {
        val code = ActivationCode.clean(serverCodes[1])
        for (i in 0 until code.length - 1) {
            if (code[i] == code[i + 1]) continue
            val swapped = code.substring(0, i) + code[i + 1] + code[i] + code.substring(i + 2)
            assertFalse("swap at $i", ActivationCode.checksumOk(swapped))
        }
    }

    @Test fun cleanIsTolerantLikeTheServer() {
        assertEquals("VCF0YMC18T1V11CK", ActivationCode.clean(" vcfo ymci-8t1v 1lck "))
        assertEquals(16, ActivationCode.clean("Z83G-BHAB-JD4T-H5BB-EXTRA").length)
        assertEquals("", ActivationCode.clean("!!--  "))
    }

    @Test fun prettyGroupsPartialInput() {
        assertEquals("Z83G-BH", ActivationCode.pretty("Z83GBH"))
        assertEquals("Z83G-BHAB-JD4T-H5BB", ActivationCode.pretty("Z83GBHABJD4TH5BB"))
    }

    @Test fun shortCodeIsNotValid() = assertFalse(ActivationCode.checksumOk("Z83GBHAB"))
}
